SELECT PersonId, 'METFORMIN' AS VarName, ABS(CHECKSUM(DrugName)) % 100000 AS DpValue, StartAt, TreatId, Caption FROM (   SELECT ot.PersonId, ot.DrugName, ot.StartAt, ot.TreatId, ai.AtcName AS Caption,     RANK() OVER ( PARTITION BY ot.PersonId ORDER BY ot.StartAt DESC ) AS ReverseOrder FROM dbo.OngoingTreatment ot   JOIN dbo.KBAtcIndex ai ON ai.AtcCode = ot.ATC AND ai.AtcName LIKE '%METFORMIN%' ) agg WHERE ( PersonId IN (/*PIDS*/) ) AND ( ReverseOrder = 1 )